const listarExecucoes = `-- name: ListarExecucoes :many
SELECT e.id, e.tipo, e.status, e.criada_em, e.iniciada_em, e.finalizada_em, e.cancelamento_solicitado, e.erro,
       e.dry_run_origem_id,
       u.nome                                                                                    AS criada_por_nome,
       count(ec.id)::int                                                                         AS total,
       (count(ec.id) FILTER (WHERE ec.status IN ('verificada', 'confirmada', 'reimpressa')))::int AS sucesso,
       (count(ec.id) FILTER (WHERE ec.status IN ('erro_antes_confirmar', 'erro_apos_confirmar')))::int AS com_erro,
       (count(ec.id) FILTER (WHERE ec.status IN ('pendente', 'em_andamento', 'confirmacao_iniciada')))::int AS restantes
FROM execucoes e
JOIN usuarios u ON u.id = e.criada_por
LEFT JOIN execucao_cotas ec ON ec.execucao_id = e.id
GROUP BY e.id, u.nome
ORDER BY e.criada_em DESC
LIMIT 50
`

type ListarExecucoesRow struct {
	ID                     int64
	Tipo                   string
	Status                 string
	CriadaEm               time.Time
	IniciadaEm             *time.Time
	FinalizadaEm           *time.Time
	CancelamentoSolicitado bool
	Erro                   *string
	DryRunOrigemID         *int64
	CriadaPorNome          string
	Total                  int32
	Sucesso                int32
	ComErro                int32
	Restantes              int32
}

func (q *Queries) ListarExecucoes(ctx context.Context) ([]ListarExecucoesRow, error) {
	rows, err := q.db.Query(ctx, listarExecucoes)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListarExecucoesRow
	for rows.Next() {
		var i ListarExecucoesRow
		if err := rows.Scan(
			&i.ID,
			&i.Tipo,
			&i.Status,
			&i.CriadaEm,
			&i.IniciadaEm,
			&i.FinalizadaEm,
			&i.CancelamentoSolicitado,
			&i.Erro,
			&i.DryRunOrigemID,
			&i.CriadaPorNome,
			&i.Total,
			&i.Sucesso,
			&i.ComErro,
			&i.Restantes,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const marcarConfirmacaoIniciada = `-- name: MarcarConfirmacaoIniciada :execrows
UPDATE execucao_cotas
SET status = 'confirmacao_iniciada'
WHERE id = $1 AND status = 'em_andamento'
`

// Gravado ANTES do clique em Confirmar. Sem esta linha atualizada, o worker não clica.
func (q *Queries) MarcarConfirmacaoIniciada(ctx context.Context, id int64) (int64, error) {
	result, err := q.db.Exec(ctx, marcarConfirmacaoIniciada, id)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const marcarConfirmacoesPendentesComoErro = `-- name: MarcarConfirmacoesPendentesComoErro :execrows
UPDATE execucao_cotas
SET status = 'erro_apos_confirmar', erro_tipo = 'inesperado', finalizada_em = now(),
    erro = 'o resultado da confirmação não chegou à plataforma: o lance pode ter sido registrado, confira no Histórico'
WHERE execucao_id = $1 AND status = 'confirmacao_iniciada'
`

// Na finalização, cota que ficou em confirmacao_iniciada (o worker não conseguiu informar
// o resultado) vai para conferência manual.
func (q *Queries) MarcarConfirmacoesPendentesComoErro(ctx context.Context, execucaoID int64) (int64, error) {
	result, err := q.db.Exec(ctx, marcarConfirmacoesPendentesComoErro, execucaoID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const posicaoNaFila = `-- name: PosicaoNaFila :one
SELECT count(*)::int
FROM execucoes o, execucoes e
WHERE e.id = $1 AND o.status = 'na_fila' AND (o.criada_em, o.id) <= (e.criada_em, e.id)
`

func (q *Queries) PosicaoNaFila(ctx context.Context, id int64) (int32, error) {
	row := q.db.QueryRow(ctx, posicaoNaFila, id)
	var column_1 int32
	err := row.Scan(&column_1)
	return column_1, err
}

const recuperarCotasDeTravasVencidas = `-- name: RecuperarCotasDeTravasVencidas :execrows

UPDATE execucao_cotas ec
SET status    = CASE WHEN ec.status = 'em_andamento' THEN 'pendente' ELSE 'erro_apos_confirmar' END,
    erro_tipo = CASE WHEN ec.status = 'em_andamento' THEN NULL ELSE 'inesperado' END,
    erro      = CASE WHEN ec.status = 'em_andamento' THEN NULL
                     ELSE 'o worker parou depois de iniciar a confirmação: o lance pode ter sido registrado, confira no Histórico' END
FROM execucoes e
WHERE e.id = ec.execucao_id
  AND e.status = 'em_andamento' AND e.trava_ate < now()
  AND ec.status IN ('em_andamento', 'confirmacao_iniciada')
`

// ===== Worker (rotas internas) =====
// Worker caiu (trava vencida): cota em_andamento volta a pendente (a confirmação não
// tinha começado). Cota em confirmacao_iniciada NUNCA volta: vira erro_apos_confirmar.
func (q *Queries) RecuperarCotasDeTravasVencidas(ctx context.Context) (int64, error) {
	result, err := q.db.Exec(ctx, recuperarCotasDeTravasVencidas)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const renovarTrava = `-- name: RenovarTrava :one
UPDATE execucoes
SET trava_ate = now() + interval '2 minutes'
WHERE id = $1 AND worker = $2 AND status = 'em_andamento'
RETURNING cancelamento_solicitado
`

type RenovarTravaParams struct {
	ID     int64
	Worker *string
}

func (q *Queries) RenovarTrava(ctx context.Context, arg RenovarTravaParams) (bool, error) {
	row := q.db.QueryRow(ctx, renovarTrava, arg.ID, arg.Worker)
	var cancelamento_solicitado bool
	err := row.Scan(&cancelamento_solicitado)
	return cancelamento_solicitado, err
}

const reservarProximaExecucao = `-- name: ReservarProximaExecucao :one
UPDATE execucoes
SET status = 'em_andamento', worker = $1, trava_ate = now() + interval '2 minutes',
    iniciada_em = COALESCE(iniciada_em, now())
WHERE id = (
    SELECT p.id
    FROM execucoes p
    WHERE p.status = 'na_fila' AND NOT p.cancelamento_solicitado AND p.tipo = ANY($2::text[])
      AND NOT EXISTS (SELECT 1 FROM execucoes o WHERE o.credencial = p.credencial AND o.status = 'em_andamento')
    ORDER BY p.criada_em, p.id
    LIMIT 1
    FOR UPDATE SKIP LOCKED
)
RETURNING id, tipo, credencial
`

type ReservarProximaExecucaoParams struct {
	Worker *string
	Tipos  []string
}

type ReservarProximaExecucaoRow struct {
	ID         int64
	Tipo       string
	Credencial string
}

func (q *Queries) ReservarProximaExecucao(ctx context.Context, arg ReservarProximaExecucaoParams) (ReservarProximaExecucaoRow, error) {
	row := q.db.QueryRow(ctx, reservarProximaExecucao, arg.Worker, arg.Tipos)
	var i ReservarProximaExecucaoRow
	err := row.Scan(&i.ID, &i.Tipo, &i.Credencial)
	return i, err
}

const resumoCotasDaExecucao = `-- name: ResumoCotasDaExecucao :one
SELECT (count(*) FILTER (WHERE status IN ('erro_antes_confirmar', 'erro_apos_confirmar')))::int AS com_erro,
       (count(*) FILTER (WHERE status IN ('pendente', 'em_andamento')))::int               AS restantes,
       (count(*) FILTER (WHERE status = 'confirmacao_iniciada'))::int                     AS em_confirmacao
FROM execucao_cotas
WHERE execucao_id = $1
`

type ResumoCotasDaExecucaoRow struct {
	ComErro       int32
	Restantes     int32
	EmConfirmacao int32
}

func (q *Queries) ResumoCotasDaExecucao(ctx context.Context, execucaoID int64) (ResumoCotasDaExecucaoRow, error) {
	row := q.db.QueryRow(ctx, resumoCotasDaExecucao, execucaoID)
	var i ResumoCotasDaExecucaoRow
	err := row.Scan(&i.ComErro, &i.Restantes, &i.EmConfirmacao)
	return i, err
}

const solicitarCancelamento = `-- name: SolicitarCancelamento :exec
UPDATE execucoes
SET cancelamento_solicitado = true, cancelada_por = $1
WHERE id = $2
`

type SolicitarCancelamentoParams struct {
	UsuarioID *int64
	ID        int64
}

// O worker vê o pedido ao iniciar a próxima cota ou ao renovar a trava.
func (q *Queries) SolicitarCancelamento(ctx context.Context, arg SolicitarCancelamentoParams) error {
	_, err := q.db.Exec(ctx, solicitarCancelamento, arg.UsuarioID, arg.ID)
	return err
}

